// Go 的杀手锏:你根本不用手写事件循环
for {
    conn, _ := ln.Accept()
    go handle(conn)      // 每连接一个 goroutine,就这一行
}

func handle(conn net.Conn) {
    // 这里可以放心写「阻塞」代码:
    result := http.Get("http://slow-api")  // 看起来阻塞
    // 但 Go runtime 会在它等 IO 时把这个 goroutine 挪开,
    // 底层用 epoll 复用线程 —— 你写同步代码,拿到异步性能
}

