// C/C++ 手写 epoll 事件循环的骨架
int ep = epoll_create1(0);
epoll_ctl(ep, EPOLL_CTL_ADD, lfd, &ev);   // 把监听 fd 加进去
for (;;) {
    int n = epoll_wait(ep, events, MAX, -1);  // 只返回就绪的
    for (int i = 0; i < n; i++) {
        if (events[i].data.fd == lfd) accept_new(ep);
        else handle_ready(events[i].data.fd);  // 绝不能阻塞!
    }
}
